/* Auto-theorie B — modules 1, 3, 4, 6, 7 en 8.
   Bronnen: RVV 1990, WVW 1994, Reglement rijbewijzen, Regeling voertuigen.
   Vraagstijl: zie docs/examenstijl.md. Elke vraag heeft een sleutel k, uniek
   binnen de module, zodat het vraag-id niet aan de positie in de array hangt. */
window.MODULES2 = [
{
  id:'weg', nr:1, titel:'Gebruik van de weg', kleur:'--m-weg',
  samenvatting:'Plaats op de weg, snelheden, inhalen, afstand houden, stilstaan en parkeren.',
  lessons:[
    {t:'Rechts houden', b:'Je houdt zoveel mogelijk rechts. Op een weg met rijstroken binnen de bebouwde kom mag je vrij een rijstrook kiezen; buiten de bebouwde kom gebruik je de rechterstrook en de linker alleen om in te halen.', a:'RVV 1990, art. 3'},
    {t:'Waar rijd je met welk voertuig', b:'Motorvoertuigen horen op de rijbaan. Fietsers en bromfietsers gebruiken het fietspad of fiets/bromfietspad als dat er is. Voetgangers lopen op het trottoir of, als dat ontbreekt, zoveel mogelijk links langs de weg.', a:'RVV 1990, art. 3, 4 en 10'},
    {t:'Maximumsnelheden voor een personenauto', b:'Bebouwde kom 50. Buiten de bebouwde kom 80. Autoweg 100. Autosnelweg 100 tussen 06.00 en 19.00 uur, daarbuiten wat op de borden staat. Erf 15. Borden gaan altijd voor deze standaardwaarden.', a:'RVV 1990, art. 20, 21 en 45'},
    {t:'Met een aanhanger of caravan', b:'Met een aanhangwagen rijd je op de autosnelweg en autoweg maximaal 90 km/h en op andere wegen buiten de bebouwde kom maximaal 80 km/h.', a:'RVV 1990, art. 22', ill:'aanhanger'},
    {t:'Inhalen doe je links', b:'Je haalt links in. Rechts inhalen mag als de voorligger duidelijk heeft aangegeven linksaf te slaan, en op rijstroken waar het verkeer in rijen rijdt en jouw rij sneller gaat.', a:'RVV 1990, art. 11'},
    {t:'Waar je niet mag inhalen', b:'Niet vlak voor of op een zebrapad, niet vlak voor of op een spoorwegovergang, en niet waar bord F1 of F3 staat of een doorgetrokken streep ligt.', a:'RVV 1990, art. 11, 12 en 76'},
    {t:'Afstand houden', b:'Hou zoveel afstand dat je kunt stoppen als de voorligger plotseling remt. De vuistregel is twee seconden; bij regen, mist of een zware auto maak je er drie van.', a:'RVV 1990, art. 19', ill:'tweeseconden'},
    {t:'Stilstaan mag niet overal', b:'Niet op een kruispunt, op een overweg, op een zebrapad of binnen vijf meter ervoor, langs een gele doorgetrokken streep, in een tunnel of op de rijbaan van een autosnelweg of autoweg.', a:'RVV 1990, art. 23'},
    {t:'Parkeren mag nog minder vaak', b:'Niet bij een kruispunt binnen vijf meter, niet voor een inrit of uitrit, niet langs een gele onderbroken streep, niet op een gehandicaptenplaats zonder kaart en niet zo dat je anderen hindert.', a:'RVV 1990, art. 24'},
    {t:'Verlichting', b:'Bij duisternis en bij slecht zicht voer je dimlicht. Mistlicht achter mag alleen als het zicht minder is dan 50 meter. Overdag is dagrijverlichting verplicht op auto’s die er vanaf fabriek mee zijn uitgerust.', a:'RVV 1990, art. 32 t/m 36', ill:'mist'},
    {t:'Gordels en kinderen', b:'Iedereen in de auto draagt een gordel. Kinderen kleiner dan 1,35 meter zitten in een goedgekeurd kinderzitje. Jij als bestuurder bent verantwoordelijk voor passagiers onder de 18.', a:'RVV 1990, art. 59 en 60', ill:'gordel'},
    {t:'Telefoon vasthouden mag niet', b:'Je mag tijdens het rijden geen mobiel elektronisch apparaat vasthouden. Handsfree bellen mag, maar ook dat kost aandacht.', a:'RVV 1990, art. 61a'}
  ],
  questions:[
    {t:'mc', k:'snelheid-buitenkom', b:'weg-buitenkom', v:'Je rijdt hier buiten de bebouwde kom. Hoe hard mag je maximaal?', o:['50 km per uur','80 km per uur','100 km per uur'], a:1, u:'Buiten de bebouwde kom geldt standaard 80 km per uur, tenzij borden iets anders aangeven.', art:'RVV 1990, art. 21'},
    {t:'mc', k:'snelheid-snelweg-dag', b:'weg-autosnelweg', v:'Je rijdt hier om drie uur ’s middags. Welke snelheid staat er overdag op bijna alle Nederlandse autosnelwegen?', o:['80 km per uur','100 km per uur','130 km per uur'], a:1, u:'Tussen 06.00 en 19.00 uur geldt op vrijwel het hele hoofdwegennet 100 km per uur. ’s Avonds en ’s nachts staat op de borden wat daar geldt. Kijk dus altijd naar de bebording.', art:'RVV 1990, art. 21'},
    {t:'mc', k:'snelheid-caravan', b:'voert-aanhanger', v:'Je rijdt met een caravan op de autosnelweg. Hoe hard mag je maximaal?', o:['80 km per uur','90 km per uur','Net zo hard als zonder caravan'], a:1, u:'Met een aanhangwagen of caravan rijd je maximaal 90 km per uur op de autosnelweg en de autoweg.', art:'RVV 1990, art. 22'},
    {t:'jn', k:'snelheid-erf', b:'bijz-erf', v:'Je rijdt hier een erf op. Mag je hier 30 km per uur rijden?', a:1, u:'Nee. Op een erf rijd je stapvoets: niet harder dan 15 km per uur.', art:'RVV 1990, art. 45'},
    {t:'mc', k:'rechts-inhalen', v:'Je wilt een auto rechts voorbijrijden. Wanneer mag dat?', o:['Als de bestuurder voor je duidelijk heeft aangegeven dat hij linksaf gaat','Als de linkerrijstrook vol staat en de rechter vrij is','Als je richting aangeeft en genoeg ruimte hebt'], a:0, u:'Rechts inhalen mag als de bestuurder voor je duidelijk heeft aangegeven linksaf te willen slaan. Ook bij rijen verkeer op rijstroken mag je rechts sneller gaan; dat heet geen inhalen.', art:'RVV 1990, art. 11'},
    {t:'multi', k:'inhalen-verboden', b:'weg-inhalen-streep', v:'Je wilt gaan inhalen. In welke van deze situaties mag dat niet? Tik alles aan wat klopt.', o:['Vlak voor een zebrapad','Op een overweg','Op een weg met drie rijstroken','Waar een bord het inhalen van motorvoertuigen verbiedt','Bij een doorgetrokken streep aan jouw kant'], a:[0,1,3,4], u:'Een zebrapad, een overweg, een inhaalverbodsbord en een doorgetrokken streep aan jouw kant sluiten inhalen uit. Op een brede weg mag je gewoon inhalen.', art:'RVV 1990, art. 11, 12 en 76'},
    {t:'fill', k:'volgafstand-seconden', b:'veilig-volgafstand', v:'Je rijdt op een droge weg achter een andere auto. Hoeveel seconden afstand hou je als vuistregel? (alleen het getal)', a:'2', u:'Twee seconden bij droog weer, drie bij regen of mist. Tel na een vast punt: eenentwintig, tweeentwintig.', art:'Rijtechnische vuistregel'},
    {t:'mc', k:'mistlicht-achter', b:'veilig-mist', v:'Je rijdt hier in dichte mist. Wanneer mag je je mistlicht achter aanzetten?', o:['Zodra je je ruitenwissers nodig hebt','Als het zicht minder is dan 50 meter','Zodra het donker wordt'], a:1, u:'Mistlicht achter mag alleen als het zicht door mist, sneeuw of regen minder is dan 50 meter. Bij beter zicht verblind je er het verkeer achter je mee.', art:'RVV 1990, art. 34 lid 2'},
    {t:'jn', k:'stilstaan-zebra', b:'voorrang-zebra', v:'Je laat hier een passagier uitstappen. Mag dat?', a:1, u:'Nee. Stilstaan op een zebrapad of binnen vijf meter ervoor is verboden, ook heel even.', art:'RVV 1990, art. 23'},
    {t:'mc', k:'gele-streep-onderbroken', v:'Langs de stoeprand ligt een gele onderbroken streep. Wat betekent dat voor jou?', o:['Je mag er niet parkeren, wel kort stilstaan','Je mag er niet stilstaan en niet parkeren','Je mag er alleen laden en lossen'], a:0, u:'Een gele onderbroken streep is een parkeerverbod; stilstaan om in of uit te laten stappen mag wel. Een gele doorgetrokken streep verbiedt ook het stilstaan.', art:'RVV 1990, art. 24'},
    {t:'mc', k:'kinderzitje-lengte', b:'wet-gordel-kind', v:'Ivet is 7 jaar en 1 meter 20 groot. Hoe mag ze met je meerijden?', o:['In een goedgekeurd kinderzitje','Achterin met alleen de gewone gordel om','Voorin met alleen de gewone gordel om'], a:0, u:'Kinderen kleiner dan 1,35 meter horen in een goedgekeurd kinderbeveiligingssysteem.', art:'RVV 1990, art. 59'},
    {t:'jn', k:'handsfree-bellen', b:'wet-telefoon', v:'Je wilt onder het rijden bellen via de knoppen op je stuur. Mag dat?', a:0, u:'Ja, handsfree bellen mag. Het apparaat vasthouden mag niet. Houd er wel rekening mee dat bellen altijd aandacht kost.', art:'RVV 1990, art. 61a'},
    {t:'mc', k:'rijstrook-buitenkom', b:'weg-buitenkom', v:'Je rijdt buiten de bebouwde kom op een weg met twee rijstroken in jouw richting. Waar hoor je te rijden?', o:['Op de rechterstrook; links alleen om in te halen','Op de linkerstrook, zodat invoegers ruimte houden','Op de strook waar het op dat moment het rustigst is'], a:0, u:'Buiten de bebouwde kom hou je rechts en gebruik je de linkerstrook alleen om in te halen.', art:'RVV 1990, art. 3'},
    {t:'mc', k:'gordel-passagier-15', v:'Je passagier van 15 jaar doet zijn gordel niet om. Wie krijgt de bekeuring?', o:['Jij als bestuurder','De passagier zelf','De ouders van de passagier'], a:0, u:'Voor passagiers jonger dan 18 ben jij als bestuurder verantwoordelijk. Vanaf 18 is de passagier zelf aansprakelijk.', art:'RVV 1990, art. 59'},
    {t:'multi', k:'parkeren-verboden', v:'Waar mag je je auto niet parkeren? Tik alles aan wat klopt.', o:['Binnen vijf meter van een kruispunt','Voor een uitrit','In een gewoon parkeervak','Op een gehandicaptenplaats zonder kaart','Langs een gele onderbroken streep'], a:[0,1,3,4], u:'Alleen parkeren in een gewoon parkeervak is hier toegestaan.', art:'RVV 1990, art. 24'},
    {t:'jn', k:'parkeren-stoep', b:'weg-parkeren-stoep', v:'Je parkeert hier. Mag dat?', a:1, u:'Nee. Je parkeert op de rijbaan of in een parkeervak. Het trottoir is voor voetgangers; half op de stoep staan dwingt hen de weg op.', art:'RVV 1990, art. 10 en 24'},
    {t:'jn', k:'parkeren-uitrit', b:'weg-parkeren-uitrit', v:'Je zet je auto hier even neer om boodschappen te halen. Mag dat?', a:1, u:'Nee. Parkeren voor een inrit of uitrit is verboden, ook als je er maar kort staat.', art:'RVV 1990, art. 24'},
    {t:'jn', k:'gehandicaptenplaats', b:'weg-gehandicapt', v:'Je hebt geen gehandicaptenparkeerkaart. Mag je hier parkeren?', a:1, u:'Nee. Op deze plaats mag je alleen staan met een geldige gehandicaptenparkeerkaart, duidelijk leesbaar achter je voorruit.', art:'RVV 1990, art. 24'},
    {t:'jn', k:'stilstaan-bocht', b:'weg-stilstaan-bocht', v:'Je stopt hier even om je telefoon te pakken. Mag dat?', a:1, u:'Nee. Vlak voor een onoverzichtelijke bocht is stilstaan verboden: verkeer dat de bocht uit komt ziet je te laat.', art:'RVV 1990, art. 23'},
    {t:'mc', k:'voorsorteervak-volgen', b:'weg-voorsorteren', v:'Je staat hier in het linker voorsorteervak. Je bedenkt je en wilt toch rechtdoor. Wat doe je?', o:['Je volgt de richting van je vak en keert later om','Je gaat rechtdoor, want dat mag als het vrij is','Je wisselt snel van vak zolang je nog niet op het kruispunt bent'], a:0, u:'Je moet de richting volgen die de pijl in je voorsorteervak aangeeft. Van gedachten veranderen mag niet meer zodra je in het vak staat: anderen rekenen op je richting. Rij door en keer verderop om.', art:'RVV 1990, art. 78'},
    {t:'jn', k:'zone-30', b:'weg-30zone', v:'Je rijdt hier 50 km per uur. Mag dat?', a:1, u:'Nee. In een 30-zone geldt 30 km per uur tot het bord met het einde van de zone. Borden gaan voor de standaardsnelheid van 50.', art:'RVV 1990, art. 20'},
    {t:'mc', k:'file-naderen', b:'bijz-file', v:'Je nadert hier een file op de snelweg. Wat doe je?', o:['Je zet je alarmlichten aan en remt geleidelijk af','Je wijkt uit naar de vluchtstrook en rijdt daar door','Je rijdt door tot vlak voor de file en remt dan stevig'], a:0, u:'Met je alarmlichten waarschuw je het verkeer achter je. Rem geleidelijk en kijk in je spiegel.', art:'WVW 1994, art. 5 en RVV 1990, art. 19'},
    {t:'mc', k:'snelheid-aanhanger-buiten', b:'voert-aanhanger', v:'Je rijdt met een aanhanger op een gewone weg buiten de bebouwde kom. Hoe hard mag je maximaal?', o:['70 km per uur','80 km per uur','90 km per uur'], a:1, u:'Op gewone wegen buiten de bebouwde kom is dat 80 km per uur; op de autoweg en de autosnelweg 90.', art:'RVV 1990, art. 22'},
    {t:'jn', k:'vluchtstrook-route', b:'veilig-pech', v:'Je wilt hier stoppen om je route op te zoeken. Mag dat?', a:1, u:'Nee. De vluchtstrook is alleen voor noodgevallen, zoals pech of een ongeval. Zoek je route op bij een parkeerplaats of tankstation.', art:'RVV 1990, art. 43'},
    {t:'mc', k:'rijstrook-binnenkom', b:'weg-binnenkom', v:'Je rijdt hier binnen de bebouwde kom op een weg met twee rijstroken in jouw richting. Wat geldt?', o:['Je mag vrij kiezen welke rijstrook je gebruikt','Je moet rechts blijven en links alleen gebruiken om in te halen','Je mag links alleen rijden als je gaat afslaan'], a:0, u:'Binnen de bebouwde kom mag je op een weg met meerdere rijstroken vrij kiezen welke strook je gebruikt.', art:'RVV 1990, art. 3'},
    {t:'fill', k:'snelheid-binnenkom', b:'weg-binnenkom', v:'Je rijdt hier de bebouwde kom binnen. Hoe hard mag je maximaal? (alleen het getal)', a:'50', u:'Binnen de bebouwde kom geldt 50 km per uur, tenzij borden iets anders aangeven, zoals in een 30-zone.', art:'RVV 1990, art. 20'},
    {t:'mc', k:'dimlicht-slecht-zicht', b:'veilig-regen', v:'Het gaat overdag hard regenen en het zicht wordt slecht. Wat doe je met je verlichting?', o:['Je voert dimlicht','Je laat je dagrijverlichting branden; dat is genoeg','Je zet je groot licht aan om beter te zien'], a:0, u:'Bij duisternis en bij slecht zicht overdag is dimlicht verplicht. Dagrijverlichting brandt alleen voor, niet achter, dus ben je dan slecht zichtbaar.', art:'RVV 1990, art. 32'},
    {t:'jn', k:'groot-licht-tegenligger', b:'veilig-verblinding', v:'Je rijdt hier met groot licht. Mag je het aan laten staan?', a:1, u:'Nee. Je dimt tijdig voor tegenliggers, en ook als je dicht achter een voorligger rijdt.', art:'RVV 1990, art. 32 lid 2'},
    {t:'mc', k:'telefoon-stoplicht', b:'wet-telefoon', v:'Je staat stil voor een rood licht. Je telefoon gaat. Wat geldt?', o:['Je mag hem niet vastpakken, ook niet terwijl je stilstaat','Je mag hem pakken, want je rijdt op dat moment niet','Je mag hem pakken zolang je hem alleen voor navigatie gebruikt'], a:0, u:'Het verbod geldt voor de bestuurder van een rijdend en van een stilstaand voertuig in het verkeer, dus ook voor het stoplicht.', art:'RVV 1990, art. 61a'},
    {t:'mc', k:'rijen-verkeer', v:'Het verkeer rijdt in rijen naast elkaar. Jouw rij gaat sneller dan de rij links van je. Wat geldt?', o:['Dit mag; sneller gaan dan de rij naast je is geen inhalen','Dit is verboden rechts inhalen, dus je moet afremmen','Dit mag alleen binnen de bebouwde kom'], a:0, u:'Als het verkeer op rijstroken in rijen rijdt, is sneller gaan dan de rij naast je geen inhalen.', art:'RVV 1990, art. 11'},
    {t:'multi', k:'veilig-weggebruik', v:'Je let op veilig gebruik van de weg. Wat hoort daarbij? Tik alles aan wat klopt.', o:['Zoveel mogelijk rechts houden','Twee seconden afstand houden','Links blijven rijden omdat je dan sneller opschiet','Richting aangeven voor elke manoeuvre','Dimmen voor tegenliggers'], a:[0,1,3,4], u:'Links blijven rijden zonder in te halen is hinderlijk en buiten de bebouwde kom ook verboden.', art:'RVV 1990, art. 3, 19, 32 en 55'},
    {t:'jn', k:'fietspad-verplicht', v:'Langs de weg ligt een verplicht fietspad. Mag een fietser dan toch op jouw rijbaan rijden?', a:1, u:'Nee. Is er een verplicht fietspad, dan moet de fietser dat gebruiken.', art:'RVV 1990, art. 5'},
    {t:'mc', k:'parkeerschijf-blauwe-zone', b:'weg-parkeren-blauw', v:'Je wilt hier parkeren. Wat moet je doen?', o:['Een parkeerschijf duidelijk zichtbaar achter je voorruit leggen','Een kaartje kopen bij de automaat verderop','Niets; parkeren is hier gratis en onbeperkt'], a:0, u:'In een parkeerschijfzone zet je je parkeerschijf op het tijdstip van aankomst en blijf je binnen de aangegeven tijd.', art:'RVV 1990, art. 25'},
    {t:'hotspot', k:'rijstrook-kruis-aantikken', b:'weg-rijstrook-kruis', v:'Tik de rijstrook aan die je hier niet mag gebruiken.', a:{x:34,y:30,w:32,h:60}, u:'Boven die strook brandt een rood kruis: hij is gesloten. Verlaat hem tijdig en rustig; pas als het kruis weg is mag je er weer rijden.', art:'RVV 1990, art. 73'}
  ],
  puzzles:[]
},
{
  id:'bijzonder', nr:3, titel:'Bijzondere wegen en manoeuvres', kleur:'--m-bijzonder',
  samenvatting:'Autosnelweg, erf, rotonde, tunnel, spoorwegovergang, in- en uitvoegen, keren en achteruitrijden.',
  lessons:[
    {t:'Wie mag op de autosnelweg', b:'Alleen motorvoertuigen die minimaal 60 km/h kunnen én mogen rijden. Op de autoweg is dat 50 km/h. Fietsers, bromfietsers, landbouwvoertuigen en voetgangers mogen er niet komen.', a:'RVV 1990, art. 42 en bijlage 1 borden G1 en G3', ill:'snelweg'},
    {t:'Keren en achteruitrijden op de snelweg', b:'Op een autosnelweg en autoweg mag je niet keren en niet achteruitrijden. Mis je je afrit, dan rijd je door tot de volgende.', a:'RVV 1990, art. 43'},
    {t:'Invoegen en uitvoegen', b:'Invoegen is een bijzondere manoeuvre: je past je snelheid aan die van de doorgaande rijbaan aan en laat dat verkeer voorgaan. Uitvoegen doe je tijdig, op de uitvoegstrook, niet door hard te remmen op de rijbaan.', a:'RVV 1990, art. 54', ill:'snelweg'},
    {t:'Vluchtstrook en spitsstrook', b:'De vluchtstrook is alleen voor noodgevallen. Een spitsstrook is een vluchtstrook die als rijstrook is opengesteld; dat zie je aan een groene pijl boven de strook. Staat er een rood kruis, dan mag je er niet rijden.', a:'RVV 1990, art. 1, 43 en 73'},
    {t:'Pech op de snelweg', b:'Rijd zo ver mogelijk naar rechts, zet je alarmlichten aan, stap rechts uit, ga achter de vangrail staan en bel het alarmnummer of de wegenwacht. Een gevarendriehoek plaats je niet op de snelweg; op andere wegen wel, zo’n 30 meter voor de auto.', a:'RVV 1990, art. 43 en 58', ill:'pech'},
    {t:'Erf', b:'Op een erf mag je niet sneller dan 15 km per uur rijden. Voetgangers mogen de hele breedte gebruiken en spelen is toegestaan. Parkeren mag alleen in de vakken. Een erf verlaten is een bijzondere manoeuvre.', a:'RVV 1990, art. 44, 45, 46 en 54', ill:'erf'},
    {t:'Rotonde', b:'Volg de rotonde rechtsom (bord D1). Haaientanden bij de oprit betekenen voorrang verlenen aan het verkeer op de rotonde. Bij het verlaten geef je rechts richting aan en laat je rechtdoorgaande fietsers en voetgangers voorgaan.', a:'RVV 1990, art. 18 en bijlage 1 bord D1', ill:'rotonde'},
    {t:'Tunnel', b:'Doe je dimlicht aan, hou afstand en stem je radio af op de tunnelzender. Bij file in een tunnel: motor uit, alarmlichten aan. Bij brand verlaat je de auto met de sleutel erin en loop je naar de dichtstbijzijnde nooduitgang.', a:'RVV 1990, art. 32 en bijlage 1 bord L13', ill:'tunnel'},
    {t:'Spoorwegovergang', b:'De trein gaat altijd voor. Rijd pas op als je er zeker helemaal voorbij kunt komen. Rode knipperlichten betekenen stoppen, ook als de bomen nog openstaan. Blijf je toch staan op het spoor: rijd door de bomen heen, die breken af.', a:'RVV 1990, art. 14 en 71', ill:'spoorweg'},
    {t:'Bijzondere manoeuvres op een rij', b:'Wegrijden, achteruitrijden, keren, een inrit of uitrit in- of uitrijden, van rijstrook wisselen, invoegen, uitvoegen en een erf verlaten. Bij al deze manoeuvres laat je het overige verkeer voorgaan.', a:'RVV 1990, art. 54'},
    {t:'Inhalen van langzaam verkeer', b:'Een fiets of bromfiets haal je in met als vuistregel minstens anderhalve meter zijdelingse afstand. Bij bord F1 mag je motorvoertuigen niet inhalen, maar een fiets wel.', a:'RVV 1990, art. 11 en bijlage 1 bord F1'},
    {t:'Busbaan en busstrook', b:'Bij bord F13 mag je als automobilist niet op de baan of strook rijden. Een busstrook met het woord BUS op het wegdek en een doorgetrokken streep mag je ook niet gebruiken.', a:'RVV 1990, art. 81 en 76'}
  ],
  questions:[
    {t:'mc', k:'minimumsnelheid-snelweg', b:'weg-autosnelweg', v:'Je rijdt hier de autosnelweg op. Welke snelheid moet je voertuig minimaal kunnen en mogen rijden?', o:['40 km per uur','50 km per uur','60 km per uur'], a:2, u:'Op de autosnelweg is dat 60 km per uur, op de autoweg 50 km per uur.', art:'RVV 1990, art. 42'},
    {t:'jn', k:'achteruit-snelweg', b:'weg-autosnelweg', v:'Je mist hier je afrit. Mag je een stukje achteruitrijden?', a:1, u:'Nee. Keren en achteruitrijden zijn op de autosnelweg en de autoweg verboden. Rijd door tot de volgende afrit.', art:'RVV 1990, art. 43'},
    {t:'mc', k:'invoegen', b:'weg-invoegen', v:'Je voegt hier in vanaf de invoegstrook. Wat doe je?', o:['Je past je snelheid aan en laat het doorgaande verkeer voorgaan','Je remt af en wacht tot de strook ophoudt','Je rijdt door; het verkeer op de rijbaan maakt ruimte'], a:0, u:'Invoegen is een bijzondere manoeuvre. Je rijdt mee op snelheid en laat het doorgaande verkeer voorgaan.', art:'RVV 1990, art. 54'},
    {t:'mc', k:'groene-pijl-spitsstrook', b:'tekens-matrix', v:'Boven de vluchtstrook brandt een groene pijl. Wat betekent dat voor jou?', o:['De strook is opengesteld als spitsstrook, je mag erop rijden','Alleen hulpdiensten mogen die strook gebruiken','Je moet die strook juist verlaten'], a:0, u:'Een groene pijl boven de strook betekent dat je hem mag gebruiken. Een rood kruis betekent gesloten.', art:'RVV 1990, art. 73'},
    {t:'multi', k:'pech-snelweg', b:'veilig-pech', v:'Je krijgt hier pech. Wat doe je? Tik alles aan wat klopt.', o:['Zo ver mogelijk naar rechts gaan','Alarmlichten aanzetten','Een gevarendriehoek 30 meter achter je auto zetten','Rechts uitstappen','Achter de vangrail wachten'], a:[0,1,3,4], u:'Op de autosnelweg plaats je geen gevarendriehoek; langs de rijbaan lopen is daar te gevaarlijk. Op andere wegen doe je dat wel.', art:'RVV 1990, art. 43 en 58'},
    {t:'mc', k:'snelheid-erf', b:'bijz-erf', v:'Je rijdt hier. Hoe hard mag je maximaal?', o:['15 km per uur','30 km per uur','50 km per uur'], a:0, u:'Op een erf rijd je stapvoets: maximaal 15 km per uur.', art:'RVV 1990, art. 45'},
    {t:'jn', k:'parkeren-erf', b:'bijz-erf', v:'Je zet je auto hier langs de kant neer, buiten een vak. Mag dat?', a:1, u:'Nee. Op een erf mag je alleen parkeren in de vakken of op plaatsen met de letter P.', art:'RVV 1990, art. 46'},
    {t:'mc', k:'erf-verlaten', b:'bijz-erf-uit', v:'Je rijdt hier het erf af, de weg op. Wat moet je doen?', o:['Al het verkeer voor laten gaan, ook voetgangers','Alleen verkeer van rechts voor laten gaan','Doorrijden; het verkeer op de weg moet je ruimte geven'], a:0, u:'Een erf verlaten is een bijzondere manoeuvre. Je laat al het verkeer voorgaan.', art:'RVV 1990, art. 54'},
    {t:'mc', k:'rotonde-verlaten', b:'bo-rotonde', v:'Je rijdt hier de rotonde af. Wat geef je aan?', o:['Rechts richting','Links richting','Niets, je rijdt gewoon rechtdoor'], a:0, u:'Bij het verlaten van de rotonde geef je rechts richting aan. Bij het oprijden geef je normaal gesproken niets aan.', art:'RVV 1990, art. 55'},
    {t:'multi', k:'file-tunnel', b:'bijz-tunnel', v:'Je staat hier stil in een file. Wat doe je? Tik alles aan wat klopt.', o:['De motor uitzetten','Alarmlichten aanzetten','Afstand houden tot de auto voor je','Keren en terugrijden','De radio op de tunnelzender zetten'], a:[0,1,2,4], u:'Keren in een tunnel is levensgevaarlijk en verboden. De rest helpt de luchtkwaliteit en de hulpdiensten.', art:'WVW 1994, art. 5'},
    {t:'mc', k:'tunnelbrand-sleutel', b:'bijz-tunnel', v:'Er is brand in de tunnel en je laat je auto achter. Wat doe je met de sleutel?', o:['Je laat hem in het contact zitten','Je neemt hem mee','Je legt hem in de kofferbak'], a:0, u:'Laat de sleutel in het contact, zodat hulpdiensten de auto kunnen verplaatsen. Loop daarna naar de dichtstbijzijnde nooduitgang.', art:'Tunnelveiligheidsinstructies'},
    {t:'jn', k:'overweg-oprijden', b:'bijz-overweg-licht', v:'De bomen gaan omhoog, maar aan de overkant staat het verkeer stil. Mag je oprijden?', a:1, u:'Nee. Je rijdt pas op als je er zeker helemaal voorbij kunt komen. Anders blijf je op het spoor staan.', art:'RVV 1990, art. 14'},
    {t:'mc', k:'overweg-vast', b:'bijz-overweg-licht', v:'Je staat met je auto stil op de overweg en de bomen gaan dicht. Wat doe je?', o:['Doorrijden; de bomen breken af','Wachten en op je claxon drukken','Achteruitrijden onder de boom door'], a:0, u:'Rijd door. De bomen zijn gemaakt om af te breken. Blijf nooit op het spoor staan.', art:'RVV 1990, art. 71'},
    {t:'mc', k:'fietser-inhalen-afstand', b:'veilig-fietser-inhalen', v:'Je haalt hier een fietser in. Hoeveel ruimte hou je als vuistregel opzij?', o:['Een halve meter','Anderhalve meter','Drie meter'], a:1, u:'Hou minstens anderhalve meter aan, zodat een slingerende fietser niet in gevaar komt. Het staat niet als getal in de wet, maar je wordt er wel op afgerekend als het misgaat.', art:'WVW 1994, art. 5 en RVV 1990, art. 11'},
    {t:'jn', k:'inhaalverbod-fietser', v:'Er staat een bord dat het inhalen van motorvoertuigen verbiedt. Mag je een fietser toch inhalen?', a:0, u:'Ja. Dat verbod geldt alleen voor het onderling inhalen van motorvoertuigen. Een fiets is geen motorvoertuig.', art:'RVV 1990, bijlage 1 bord F1'},
    {t:'multi', k:'bijzondere-manoeuvres', v:'Welke van deze dingen die je doet zijn bijzondere manoeuvres? Tik alles aan wat klopt.', o:['Uitvoegen','Een inrit inrijden','Rechtdoor rijden op een rotonde','Keren','Wegrijden vanaf een parkeerplaats'], a:[0,1,3,4], u:'Rechtdoor rijden op een rotonde is geen bijzondere manoeuvre; daar gelden de gewone voorrangsregels.', art:'RVV 1990, art. 54'},
    {t:'jn', k:'busstrook-rijden', b:'weg-busstrook', v:'Je hebt haast en de strook rechts van je is leeg. Mag je er rijden?', a:1, u:'Nee. Een busbaan of busstrook is alleen voor lijnbussen, en de doorgetrokken streep mag je bovendien niet overschrijden.', art:'RVV 1990, art. 81 en 76'},
    {t:'mc', k:'rotonde-oprijden', b:'bo-rotonde', v:'Je nadert hier de rotonde en er rijdt een auto op de rotonde. Wat doe je?', o:['Je laat de auto op de rotonde voorgaan','Je rijdt door; je komt van rechts','Je wacht tot de hele rotonde leeg is'], a:0, u:'De haaientanden wijzen naar jou: je laat het verkeer dat al op de rotonde rijdt voorgaan. Wachten tot de rotonde leeg is houdt het verkeer onnodig op.', art:'RVV 1990, art. 80'},
    {t:'jn', k:'bromfiets-autoweg', b:'weg-autoweg', v:'Je ziet hier een bromfietser rijden. Mag dat?', a:1, u:'Nee. Een bromfiets kan en mag geen 50 km per uur rijden en hoort dus niet op de autoweg.', art:'RVV 1990, art. 42'},
    {t:'mc', k:'keren-smalle-weg', b:'bijz-keren', v:'Je wilt hier keren. Wat geldt?', o:['Keren is een bijzondere manoeuvre; al het verkeer gaat voor','Je staat stil, dus het andere verkeer moet op je wachten','Het verkeer van rechts gaat voor, de rest niet'], a:0, u:'Keren is een bijzondere manoeuvre. Doe het op een overzichtelijke plek en laat iedereen voorgaan.', art:'RVV 1990, art. 54'},
    {t:'mc', k:'te-laat-uitvoegen', b:'weg-autosnelweg', v:'Je zit nog op de linkerrijstrook en je afrit komt eraan. Wat doe je?', o:['Doorrijden naar de volgende afrit','Stevig remmen en schuin naar rechts oversteken','Alarmlichten aanzetten en alsnog uitvoegen'], a:0, u:'Te laat uitvoegen veroorzaakt ongelukken. Rijd door naar de volgende afrit en keer pas buiten de snelweg.', art:'WVW 1994, art. 5 en RVV 1990, art. 43'},
    {t:'fill', k:'gevarendriehoek-meters', b:'veilig-pech', v:'Je staat met pech op een gewone weg buiten de bebouwde kom. Op hoeveel meter achter je auto zet je de gevarendriehoek ongeveer? (alleen het getal)', a:'30', u:'Ongeveer 30 meter, zodat anderen op tijd gewaarschuwd zijn. Op de autosnelweg plaats je geen driehoek.', art:'RVV 1990, art. 58'},
    {t:'jn', k:'rood-kruis-rijstrook', b:'weg-rijstrook-kruis', v:'Je rijdt hier langzaam door onder het rode kruis. Mag dat?', a:1, u:'Nee. Een rood kruis betekent dat de rijstrook gesloten is. Verlaat hem tijdig en veilig en gebruik hem pas weer als het kruis weg is.', art:'RVV 1990, art. 73'},
    {t:'mc', k:'erf-spelend-kind', b:'bijz-erf', v:'Er speelt hier een kind midden op straat. Wat doe je?', o:['Je rijdt stapvoets en wacht tot het kind ruimte maakt','Je claxonneert kort zodat het kind opzij gaat','Je rijdt er langzaam langs over het trottoir'], a:0, u:'Op een erf mogen voetgangers de volle breedte van de weg gebruiken en mag er gespeeld worden. Jij past je aan.', art:'RVV 1990, art. 44'},
    {t:'mc', k:'verboden-voertuigen-snelweg', b:'weg-autosnelweg', v:'Je rijdt hier. Welk van deze voertuigen mag hier niet komen?', o:['Een landbouwtrekker','Een motor','Een auto met caravan'], a:0, u:'Een landbouwvoertuig haalt de vereiste 60 km per uur niet. Motoren en auto’s met aanhanger mogen er wel.', art:'RVV 1990, art. 42'},
    {t:'jn', k:'rotonde-linksom', b:'bo-rotonde', v:'Je moet de laatste afslag hebben. Mag je de rotonde dan linksom nemen?', a:1, u:'Nee. Het bord bij de rotonde schrijft de rijrichting voor: je volgt de rotonde rechtsom.', art:'RVV 1990, bijlage 1 bord D1'},
    {t:'sleep', k:'file-reddingsstrook', b:'bijz-file', v:'Sleep het vinkje naar de plek waar je ruimte vrijmaakt voor de hulpdiensten.', a:{x:40,y:30,w:20,h:55}, u:'Bij file maak je samen een doorgang in het midden: de linkerrij gaat naar links, de rest naar rechts. Het is een dringend advies, geen wettelijke regel.', art:'RVV 1990, art. 50'},
    {t:'hotspot', k:'wegwerk-versmalling', b:'bijz-wegwerk', v:'Tik de plek aan waar je rijstrook ophoudt.', a:{x:52,y:38,w:30,h:30}, u:'Rits op tijd in: kijk ver vooruit, pas je snelheid aan en voeg vlak voor de versmalling om en om in.', art:'WVW 1994, art. 5'}
  ],
  puzzles:[
    {v:'Jij nadert een rotonde uit het zuiden en wilt de eerste afslag rechts nemen. Fietser F rijdt rechtdoor over het fietspad langs die afslag. Klik de volgorde.', scene:{type:'kruis', borden:'haaientanden-zuid', actors:[{id:'A',van:'zuid',naar:'rechts',label:'Jij',kleur:'jij'},{id:'F',van:'oost',naar:'rd',label:'F',soort:'fiets'}]}, a:['F','A'], u:'De rotonde verlaten is afslaan. De rechtdoorgaande fietser gaat voor.', art:'RVV 1990, art. 18 lid 1'},
    {v:'Jij staat op de invoegstrook (zuid). Op de doorgaande rijbaan nadert auto B. Klik de volgorde.', scene:{type:'kruis', borden:'geen', actors:[{id:'A',van:'zuid',naar:'rd',label:'Jij',kleur:'jij'},{id:'B',van:'west',naar:'rd',label:'B'}]}, a:['B','A'], u:'Invoegen is een bijzondere manoeuvre: het verkeer op de doorgaande rijbaan gaat voor.', art:'RVV 1990, art. 54'},
    {v:'Je rijdt een erf uit (zuid). Op de weg nadert auto B en op het trottoir loopt voetganger V. Klik de volgorde.', scene:{type:'uitrit', actors:[{id:'A',van:'uitrit',naar:'rd',label:'Jij',kleur:'jij'},{id:'B',van:'west',naar:'rd',label:'B'},{id:'V',van:'trottoir',naar:'rd',label:'V',soort:'voet'}]}, a:['V','B','A'], u:'Een erf verlaten is een bijzondere manoeuvre: iedereen gaat voor, ook de voetganger die je uitrit kruist.', art:'RVV 1990, art. 54'}
  ]
},
{
  id:'veilig', nr:4, titel:'Veilig rijden en noodsituaties', kleur:'--m-veilig',
  samenvatting:'Stopafstand, remmen, slippen, zicht, vermoeidheid en wat je doet bij een ongeval.',
  lessons:[
    {t:'Stopafstand = reactieafstand + remweg', b:'De reactieafstand is wat je aflegt voordat je remt, ongeveer een seconde. De remweg is wat je daarna nog aflegt. Samen is dat je stopafstand.', a:'RVV 1990, art. 19', ill:'stopafstand'},
    {t:'Twee keer zo hard is vier keer zo lange remweg', b:'De remweg neemt toe met het kwadraat van de snelheid. Van 50 naar 100 km/h is de remweg dus ongeveer vier keer zo lang, niet twee keer.', a:'RVV 1990, art. 19', ill:'stopafstand'},
    {t:'Op een natte weg', b:'Bij regen is de remweg ongeveer anderhalf tot twee keer zo lang. Bij ijzel kan dat oplopen tot tien keer. Hou daarom drie seconden afstand in plaats van twee.', a:'RVV 1990, art. 19', ill:'tweeseconden'},
    {t:'Aquaplaning', b:'Bij een laag profiel en veel water kan er een laagje water tussen band en wegdek komen. Je verliest dan grip. Niet sturen of remmen: gas los en de auto maakt vanzelf weer contact.', a:'Rijtechniek', ill:'bandprofiel'},
    {t:'Slippen', b:'Onderstuur betekent dat de voorkant rechtdoor schuift: gas los en stuur minder in. Overstuur betekent dat de achterkant uitbreekt: stuur rustig tegen, in de richting waar je heen wilt.', a:'Rijtechniek', ill:'slippen'},
    {t:'ABS gebruiken', b:'Met ABS blokkeren de wielen niet, zodat je kunt blijven sturen tijdens een noodstop. Trap het rempedaal stevig in en hou het ingetrapt; het trillen van het pedaal is normaal.', a:'Regeling voertuigen', ill:'slippen'},
    {t:'Dode hoek', b:'Rechts naast en schuin achter je zit een gebied dat je in je spiegels niet ziet. Kijk daarom altijd over je schouder voordat je van rijstrook wisselt of rechtsaf slaat. Bij een vrachtwagen is de dode hoek veel groter.', a:'WVW 1994, art. 5 en RVV 1990, art. 54', ill:'dodehoek'},
    {t:'Vermoeidheid', b:'Vermoeid rijden lijkt in reactietijd op rijden onder invloed. Stop elke twee uur, loop even, en neem bij slaperigheid een korte pauze. Koffie of raam open helpt maar kort.', a:'WVW 1994, art. 5'},
    {t:'Bij een ongeval', b:'Zet je auto veilig neer, alarmlichten aan, hesje aan. Bel 112 bij gewonden. Je mag nooit doorrijden na een ongeval; dat is een misdrijf. Wissel gegevens uit en vul een schadeformulier in.', a:'WVW 1994, art. 7', ill:'pech'},
    {t:'Hulp verlenen', b:'Zorg eerst voor je eigen veiligheid, dan die van anderen. Haal een gewonde alleen uit de auto bij acuut gevaar, zoals brand. Een helm van een motorrijder laat je af, tenzij de ademhaling in gevaar is.', a:'WVW 1994, art. 7'},
    {t:'Gevaar op de weg', b:'Je mag geen gevaar veroorzaken of het verkeer hinderen. Dat is een ruime regel waaronder ook te dicht op de voorligger rijden en onnodig links rijden vallen.', a:'WVW 1994, art. 5'},
    {t:'Rijden onder invloed', b:'De grens is 0,5 promille, voor een beginnend bestuurder 0,2 promille. Ook medicijnen met een gele sticker en drugs vallen hieronder. Alcohol vertraagt je reactie en maakt je overmoedig.', a:'WVW 1994, art. 8', ill:'alcohol'}
  ],
  questions:[
    {t:'mc', k:'stopafstand-opbouw', b:'voert-remweg', v:'Je remt voor een obstakel. Waaruit bestaat de afstand die je dan nog aflegt?', o:['Uit de reactieafstand plus de remweg','Alleen uit de remweg','Uit de remweg plus een vaste veiligheidsmarge'], a:0, u:'De stopafstand is de reactieafstand, die je aflegt voordat je remt, plus de remweg, die je aflegt terwijl je remt.', art:'Rijtechnisch gegeven'},
    {t:'mc', k:'remweg-kwadraat', b:'voert-remweg', v:'Je gaat van 50 naar 100 km per uur. Wat gebeurt er met je remweg?', o:['Die wordt ongeveer vier keer zo lang','Die wordt twee keer zo lang','Die wordt ongeveer anderhalf keer zo lang'], a:0, u:'De remweg neemt toe met het kwadraat van de snelheid: twee keer zo hard is ongeveer vier keer zo lange remweg.', art:'Rijtechnisch gegeven'},
    {t:'jn', k:'afstand-regen', b:'veilig-regen', v:'Je rijdt hier met twee seconden afstand. Is dat genoeg?', a:1, u:'Nee. Op een nat wegdek is je remweg veel langer. Maak er drie seconden van.', art:'RVV 1990, art. 19'},
    {t:'mc', k:'aquaplaning', b:'veilig-regen', v:'Je voelt het stuur licht worden en de auto drijft op het water. Wat doe je?', o:['Gas los en je stuur recht houden','Stevig remmen tot de auto grip heeft','Snel bijsturen naar de droge kant'], a:0, u:'Remmen of sturen heeft geen effect zolang de banden geen contact maken. Gas los, stuur recht, wacht tot de grip terug is.', art:'Rijtechnisch gegeven'},
    {t:'mc', k:'overstuur', b:'veilig-gladheid', v:'De achterkant van je auto breekt uit in een bocht. Wat doe je?', o:['Rustig tegensturen naar de kant waar je heen wilt','Stevig remmen tot de auto stilstaat','Gas geven zodat de auto zich rechttrekt'], a:0, u:'Bij overstuur stuur je rustig tegen, de kant op waar je heen wilt, en neem je gas terug.', art:'Rijtechnisch gegeven'},
    {t:'jn', k:'abs-pompen', v:'Je maakt een noodstop in een auto met ABS. Moet je het rempedaal pompend bedienen?', a:1, u:'Nee. Met ABS trap je het pedaal stevig in en hou je het ingetrapt. Het systeem doet het pompen voor je.', art:'Regeling voertuigen'},
    {t:'mc', k:'abs-voordeel', v:'Je remt vol met ABS. Wat levert dat je op?', o:['Je kunt blijven sturen tijdens het hard remmen','Je remweg is op elk wegdek korter','De auto remt vanzelf tot stilstand'], a:0, u:'ABS voorkomt blokkeren, zodat je kunt blijven sturen. Op los grind of verse sneeuw kan de remweg zelfs iets langer zijn.', art:'Regeling voertuigen'},
    {t:'mc', k:'dodehoek-rechtsaf', b:'veilig-dodehoek', v:'Je gaat rechtsaf. Waar let je extra op?', o:['Op de dode hoek rechts naast en schuin achter je','Op de tegenligger die ook rechtsaf wil','Op je snelheidsmeter'], a:0, u:'In de dode hoek rechts kan een fietser of bromfietser zitten. Kijk over je schouder voordat je stuurt.', art:'WVW 1994, art. 5'},
    {t:'multi', k:'ongeval-eerste-acties', b:'veilig-ongeval', v:'Je komt hier als eerste bij een ongeval met gewonden. Wat doe je? Tik alles aan wat klopt.', o:['Eerst zorgen voor je eigen veiligheid','112 bellen','Gewonden meteen uit de auto halen','Alarmlichten aan en je hesje aan','Doorrijden en het later melden'], a:[0,1,3], u:'Een gewonde verplaats je alleen bij acuut gevaar, zoals brand. Doorrijden na een ongeval is een misdrijf.', art:'WVW 1994, art. 7'},
    {t:'jn', k:'doorrijden-blikschade', v:'Je rijdt een geparkeerde auto aan. Er is alleen blikschade. Mag je doorrijden en later bellen?', a:1, u:'Nee. Doorrijden na een ongeval is strafbaar. Je laat je gegevens achter of wisselt ze ter plaatse uit.', art:'WVW 1994, art. 7'},
    {t:'mc', k:'alcohol-beginner', b:'wet-alcohol', v:'Je hebt je rijbewijs net een jaar. Welke alcoholgrens geldt voor jou?', o:['0,2 promille','0,5 promille','0,8 promille'], a:0, u:'Voor een beginnend bestuurder geldt 0,2 promille, oftewel 88 microgram per liter uitgeademde lucht. Voor ervaren bestuurders is dat 0,5.', art:'WVW 1994, art. 8'},
    {t:'mc', k:'vermoeidheid-lange-rit', v:'Je bent erg moe tijdens een lange rit. Wat helpt echt?', o:['Stoppen en minstens een kwartier rusten','Een raam openzetten en doorrijden','Een kop koffie en de muziek harder'], a:0, u:'Alleen rust helpt. De rest werkt hooguit een paar minuten en geeft een vals gevoel van alertheid.', art:'WVW 1994, art. 5'},
    {t:'jn', k:'gele-sticker-medicijn', v:'Je medicijn heeft een gele waarschuwingssticker. Kan dat je rijvaardigheid beinvloeden?', a:0, u:'Ja. Een gele sticker betekent dat het middel je rijvaardigheid kan beinvloeden. Lees de bijsluiter en overleg met je arts.', art:'WVW 1994, art. 8'},
    {t:'mc', k:'vrachtwagen-dodehoek', b:'veilig-dodehoek', v:'Je staat rechts naast een vrachtwagen die rechtsaf wil. Wat doe je?', o:['Je blijft achter de vrachtwagen wachten','Je rijdt snel door zodat je eerder bent','Je claxonneert en blijft staan waar je staat'], a:0, u:'Rechts naast de cabine zit een grote dode hoek; de chauffeur ziet je daar niet. Blijf erachter of zorg voor oogcontact.', art:'WVW 1994, art. 5'},
    {t:'fill', k:'reactietijd-seconden', b:'voert-remweg', v:'Je bent oplettend en ziet een gevaar. Hoeveel seconden duurt het ongeveer voor je remt? (alleen het getal)', a:'1', u:'Ongeveer een seconde. Bij 100 km per uur leg je in die tijd al bijna 30 meter af. Door afleiding of vermoeidheid loopt het flink op.', art:'Rijtechnisch gegeven'},
    {t:'mc', k:'onderstuur', b:'veilig-gladheid', v:'Je stuurt de bocht in, maar de auto schuift rechtdoor. Wat doe je?', o:['Gas los en minder insturen','Harder insturen tot de auto meedraait','Stevig remmen en het stuur vasthouden'], a:0, u:'Bij onderstuur verliezen de voorwielen grip. Gas los en minder insturen geeft de voorwielen hun grip terug.', art:'Rijtechnisch gegeven'},
    {t:'multi', k:'remweg-langer', v:'Wat maakt je remweg langer? Tik alles aan wat klopt.', o:['Een nat wegdek','Versleten banden','Een zware lading','Nieuwe remblokken','Een helling naar beneden'], a:[0,1,2,4], u:'Goede remblokken verkorten je remweg juist.', art:'Regeling voertuigen en RVV 1990, art. 19'},
    {t:'mc', k:'rijden-in-mist', b:'veilig-mist', v:'Je rijdt hier en je ziet minder dan 50 meter ver. Wat doe je?', o:['Dimlicht voeren, flink vaart minderen en je mistlicht achter mag aan','Groot licht aanzetten zodat je verder kijkt','Alarmlichten aanzetten en op snelheid doorrijden'], a:0, u:'Bij zicht onder de 50 meter mag je mistlicht achter voeren. Groot licht weerkaatst in de mist. Rijd zo langzaam dat je binnen je zichtafstand kunt stoppen.', art:'RVV 1990, art. 34 lid 2'},
    {t:'jn', k:'groot-licht-mist', b:'veilig-mist', v:'Je zet hier je groot licht aan om verder te kijken. Is dat verstandig?', a:1, u:'Nee. Groot licht weerkaatst in de mist en verblindt je juist. Gebruik dimlicht en zo nodig mistlicht.', art:'RVV 1990, art. 32 en 34'},
    {t:'mc', k:'ambulance-snelweg', b:'voorrang-hulpdienst', v:'Je ziet in je spiegel een ambulance met zwaailicht en sirene naderen. Wat doe je?', o:['Rustig naar rechts gaan en ruimte maken','Stevig remmen zodat hij voorbij kan','Op de vluchtstrook gaan staan en wachten'], a:0, u:'Maak voorspelbaar ruimte zonder bruusk te remmen. Bij file wordt geadviseerd samen een doorgang in het midden vrij te maken; dat is een advies, geen wettelijke regel.', art:'RVV 1990, art. 50'},
    {t:'mc', k:'licht-na-ongeval', b:'veilig-ongeval', v:'Je staat stil langs de weg na een ongeval. Welke lichten zet je aan?', o:['Je alarmlichten','Je groot licht','Je mistlicht voor'], a:0, u:'Alarmlichten waarschuwen het naderende verkeer dat er iets aan de hand is.', art:'RVV 1990, art. 58'},
    {t:'jn', k:'helm-motorrijder', v:'Je komt bij een gevallen motorrijder die gewond is en normaal ademt. Haal je zijn helm af?', a:1, u:'Nee. In principe laat je de helm zitten, tenzij de ademhaling in gevaar is. Wacht op de hulpdiensten.', art:'WVW 1994, art. 7'},
    {t:'mc', k:'rempedaal-trilt', v:'Je rempedaal trilt onder je voet tijdens een noodstop. Wat betekent dat?', o:['Het ABS werkt; blijf het pedaal ingetrapt houden','Je remmen zijn kapot; laat het pedaal los','Je remt te zacht; pomp het pedaal op'], a:0, u:'Het trillen hoort bij een werkend ABS. Hou het pedaal ingetrapt en stuur om het obstakel heen.', art:'Regeling voertuigen'},
    {t:'mc', k:'remweg-ijzel', b:'veilig-gladheid', v:'Je rijdt hier op ijzel. Hoeveel langer kan je remweg worden?', o:['Tot wel tien keer zo lang','Ongeveer twee keer zo lang','Nauwelijks langer, je banden grijpen wel'], a:0, u:'Op ijzel kan de remweg tot ongeveer tien keer zo lang worden. Rijd dan veel langzamer en hou extra afstand.', art:'RVV 1990, art. 19'},
    {t:'jn', k:'hesje-verplicht', b:'veilig-pech', v:'Je rijdt in Nederland. Ben je verplicht een veiligheidshesje in de auto te hebben?', a:1, u:'Nee, in Nederland is dat niet wettelijk verplicht, maar wel sterk aan te raden. In veel andere landen is het wel verplicht.', art:'Geen wettelijke verplichting in Nederland'},
    {t:'mc', k:'bijna-in-slaap', v:'Je merkt dat je ogen dichtvallen op de snelweg. Wat doe je?', o:['Bij de eerste veilige gelegenheid stoppen en rusten','Je raam openzetten en doorrijden tot je bestemming','Harder rijden zodat je er sneller bent'], a:0, u:'Een microslaap van een paar seconden kost op 100 km per uur al bijna 100 meter blind rijden. Stop en rust.', art:'WVW 1994, art. 5'},
    {t:'mc', k:'kind-bal', b:'veilig-kind-bal', v:'Er rolt hier een bal tussen de geparkeerde auto’s de weg op. Wat doe je?', o:['Je remt af en rekent erop dat er een kind achteraan komt','Je stuurt om de bal heen en rijdt door','Je claxonneert zodat het kind blijft staan'], a:0, u:'Achter een bal komt bijna altijd een kind. Rem af, dek je in en wees klaar om te stoppen.', art:'WVW 1994, art. 5'},
    {t:'sleep', k:'dodehoek-aanwijzen', b:'veilig-dodehoek', v:'Sleep het vinkje naar het gebied waar de chauffeur jou niet kan zien.', a:{x:37,y:64,w:46,h:26}, u:'Rechts naast en schuin achter de cabine zit de grootste dode hoek. Blijf daar weg en zorg voor oogcontact in de spiegel.', art:'WVW 1994, art. 5'}
  ],
  puzzles:[]
},
{
  id:'milieu', nr:6, titel:'Verantwoord en milieubewust rijden', kleur:'--m-milieu',
  samenvatting:'Zuinig rijden, bandenspanning, milieuzones, alcohol en drugs, afleiding, agressie en rijhulpsystemen.',
  lessons:[
    {t:'Het Nieuwe Rijden', b:'Schakel vroeg op, rijd gelijkmatig, kijk ver vooruit en laat de auto zoveel mogelijk uitrollen. Zo bespaar je brandstof en rijd je ook veiliger.', a:'Milieubeleid rijksoverheid'},
    {t:'Vroeg opschakelen', b:'Bij een benzinemotor schakel je rond 2.000 tot 2.500 toeren op, bij een diesel rond 2.000. Hoge toeren verbruiken veel meer dan nodig.', a:'Het Nieuwe Rijden'},
    {t:'Motor uit bij stilstand', b:'Sta je langer dan ongeveer een minuut stil, bijvoorbeeld voor een brug of in een file, zet dan de motor uit. Start-stopsystemen doen dit automatisch.', a:'Het Nieuwe Rijden'},
    {t:'Bandenspanning', b:'Te lage bandenspanning kost brandstof, verslechtert je wegligging en versnelt slijtage. Controleer de spanning elke twee maanden bij koude banden en gebruik de waarde uit het instructieboekje.', a:'Regeling voertuigen'},
    {t:'Gewicht en luchtweerstand', b:'Een dakkoffer of fietsendrager kost al snel tien tot twintig procent extra brandstof. Haal hem eraf als je hem niet gebruikt en laat geen onnodige spullen in de auto liggen.', a:'Het Nieuwe Rijden'},
    {t:'Airco en elektrische verbruikers', b:'Airco, stoelverwarming en achterruitverwarming kosten brandstof. Gebruik ze als het nodig is en zet ze daarna weer uit.', a:'Het Nieuwe Rijden'},
    {t:'Cruise control en zuinig rijden', b:'Cruise control houdt je snelheid constant en dat scheelt brandstof op een vlakke, rustige weg. In de stad, in druk verkeer en op glad wegdek zet je hem uit: je wilt dan zelf gas en snelheid in de hand houden. Jij blijft verantwoordelijk voor de snelheid die ter plaatse geldt.', a:'Rijprocedure B, hoofdstuk 1 en 2'},
    {t:'Milieuzone', b:'In een milieuzone mogen vervuilende voertuigen niet komen; dat is bord C22a. Een nul-emissiezone heeft bord C22c en geldt voor bedrijfs- en vrachtauto’s. Het onderbord zegt steeds welke voertuigen geweerd worden.', a:'RVV 1990, art. 86d en 86e'},
    {t:'Alcohol', b:'De grens is 0,5 promille, voor een beginnend bestuurder 0,2 promille. Alcohol wordt maar langzaam afgebroken, ongeveer één standaardglas per uur. Koffie, douchen of eten versnelt dat niet.', a:'WVW 1994, art. 8', ill:'alcohol'},
    {t:'Drugs en medicijnen', b:'Voor drugs gelden aparte grenswaarden en er wordt op straat op getest (WVW 1994, art. 8). Medicijnen met een gele sticker kunnen je rijvaardigheid beïnvloeden; die sticker komt uit de indeling van apothekersorganisatie KNMP.', a:'WVW 1994, art. 8', ill:'alcohol'},
    {t:'Afleiding', b:'Een telefoon vasthouden mag niet. Ook navigatie instellen, eten of een gesprek over je schouder kost aandacht. Zet alles klaar voordat je wegrijdt.', a:'RVV 1990, art. 61a'},
    {t:'Agressie in het verkeer', b:'Boos reageren maakt een situatie alleen gevaarlijker. Laat je niet opjagen, hou afstand en maak geen oogcontact met iemand die uitdaagt.', a:'WVW 1994, art. 5'},
    {t:'Zuinig en veilig gaan samen', b:'Ver vooruitkijken, vloeiend rijden en op tijd gas loslaten scheelt brandstof én voorkomt hard remmen. De zuinige rijstijl is ook de rustige rijstijl.', a:'Het Nieuwe Rijden'}
  ],
  questions:[
    {t:'mc', k:'opschakelen-toeren', b:'milieu-toerenteller', v:'Je rijdt een benzineauto en wilt zuinig rijden. Bij welk toerental schakel je ongeveer op?', o:['Rond 2.000 tot 2.500 toeren','Rond 1.000 toeren','Rond 4.000 toeren'], a:0, u:'Rond 2.000 tot 2.500 toeren opschakelen bespaart brandstof zonder dat de motor te zwaar belast wordt.', art:'Het Nieuwe Rijden'},
    {t:'jn', k:'bandenspanning-verbruik', b:'milieu-bandenspanning', v:'Je banden staan een halve bar te zacht. Kost je dat extra brandstof?', a:0, u:'Ja. Lage spanning geeft meer rolweerstand, dus meer verbruik, en bovendien een slechtere wegligging en snellere slijtage.', art:'Regeling voertuigen'},
    {t:'mc', k:'motor-uit-brug', b:'milieu-stilstaan', v:'Je staat hier twee minuten stil voor een open brug. Wat doe je?', o:['Je zet de motor uit','Je laat de motor stationair draaien','Je geeft af en toe gas zodat de motor warm blijft'], a:0, u:'Sta je langer dan ongeveer een minuut stil, zet de motor dan uit. Stationair draaien verbruikt brandstof zonder dat je opschiet.', art:'Het Nieuwe Rijden'},
    {t:'mc', k:'dakkoffer-verbruik', v:'Je laat je dakkoffer het hele jaar op de auto staan. Wat kost dat ongeveer aan extra brandstof?', o:['Tien tot twintig procent','Ongeveer een procent','Meer dan de helft'], a:0, u:'De extra luchtweerstand kost al snel tien tot twintig procent. Haal de koffer eraf als je hem niet gebruikt.', art:'Het Nieuwe Rijden'},
    {t:'mc', k:'milieuzone', b:'milieu-zone', v:'Je rijdt hier een zone binnen. Wat betekent dit bord voor jou?', o:['Je mag er alleen in als je auto schoon genoeg is','Je mag er alleen in met een parkeervergunning','Je mag er maximaal 30 km per uur'], a:0, u:'Dit is een milieuzone. Het onderbord zegt welke voertuigen geweerd worden. Een nul-emissiezone heeft een eigen bord en geldt voor bedrijfs- en vrachtauto’s.', art:'RVV 1990, art. 86d'},
    {t:'mc', k:'alcohol-afbraak', b:'wet-alcohol', v:'Je hebt gedronken en wilt weten wanneer je weer mag rijden. Hoeveel breekt je lichaam ongeveer per uur af?', o:['Ongeveer een standaardglas','Ongeveer drie glazen','Dat hangt af van hoeveel je gegeten hebt'], a:0, u:'Ongeveer een standaardglas per uur. Eten, koffie of een douche versnelt de afbraak niet.', art:'WVW 1994, art. 8'},
    {t:'jn', k:'koffie-nuchter', b:'wet-alcohol', v:'Je hebt te veel gedronken en drinkt een paar koppen koffie. Mag je dan weer rijden?', a:1, u:'Nee. Koffie maakt je hooguit wakkerder, maar verlaagt je alcoholpromillage niet.', art:'WVW 1994, art. 8'},
    {t:'multi', k:'zuinig-rijden', v:'Je wilt zuiniger gaan rijden. Wat hoort daarbij? Tik alles aan wat klopt.', o:['Vroeg opschakelen','Ver vooruitkijken','Vaak hard optrekken en weer afremmen','De auto laten uitrollen','Je bandenspanning op peil houden'], a:[0,1,3,4], u:'Hard optrekken en remmen is juist de duurste en gevaarlijkste rijstijl.', art:'Het Nieuwe Rijden'},
    {t:'mc', k:'bandenspanning-controle', b:'milieu-bandenspanning', v:'Hoe vaak controleer je je bandenspanning het liefst?', o:['Ongeveer elke twee maanden','Elke week','Alleen bij de APK'], a:0, u:'Ongeveer elke twee maanden, bij koude banden, met de waarde uit het instructieboekje of op de tankklep.', art:'Advies van de RDW en de bandenbranche'},
    {t:'jn', k:'telefoon-navigatie', b:'wet-telefoon', v:'Je rijdt stapvoets in de file en stelt je navigatie in op je telefoon in je hand. Mag dat?', a:1, u:'Nee. Een mobiel elektronisch apparaat vasthouden mag niet tijdens het rijden. Stel je navigatie in voordat je wegrijdt.', art:'RVV 1990, art. 61a'},
    {t:'mc', k:'agressieve-achterligger', b:'veilig-volgafstand', v:'Iemand rijdt vlak achter je en knippert met zijn lichten. Wat doe je?', o:['Rustig doorrijden en bij gelegenheid ruimte maken','Even op de rem tikken zodat hij afstand neemt','Oogcontact maken en gebaren terug'], a:0, u:'Laat je niet opjagen en ga de confrontatie niet aan. Maak op een veilig moment ruimte zodat de ander voorbij kan.', art:'WVW 1994, art. 5'},
    {t:'mc', k:'alcohol-ervaren', b:'wet-alcohol', v:'Je hebt je rijbewijs al tien jaar. Welke alcoholgrens geldt voor jou?', o:['0,5 promille','0,2 promille','0,8 promille'], a:0, u:'0,5 promille, oftewel 220 microgram alcohol per liter uitgeademde lucht. Voor beginnende bestuurders is dat 0,2.', art:'WVW 1994, art. 8'},
    {t:'jn', k:'airco-verbruik', v:'Je zet je airco aan op een warme dag. Kost dat extra brandstof?', a:0, u:'Ja. De airco belast de motor. Gebruik hem als het nodig is en zet hem daarna weer uit.', art:'Het Nieuwe Rijden'},
    {t:'mc', k:'snelheid-verbruik', b:'weg-autosnelweg', v:'Je rijdt hier 100 in plaats van 130 km per uur. Wat doet dat met je verbruik?', o:['Het daalt flink, vooral door minder luchtweerstand','Het blijft ongeveer gelijk','Het stijgt, want je rijdt langer'], a:0, u:'De luchtweerstand neemt sterk toe met de snelheid. Rustiger rijden op de snelweg scheelt aanzienlijk.', art:'Het Nieuwe Rijden'},
    {t:'mc', k:'medicijnsticker-kleur', v:'Welke kleur sticker op een medicijndoosje waarschuwt dat het je rijvaardigheid kan beinvloeden?', o:['Een gele sticker','Een rode sticker','Een blauwe sticker'], a:0, u:'Een gele sticker betekent dat het middel de rijvaardigheid kan beinvloeden. Lees altijd de bijsluiter. De indeling komt van apothekersorganisatie KNMP.', art:'KNMP-indeling rijvaardigheid'},
    {t:'multi', k:'afleiding', b:'wet-telefoon', v:'Wat vergroot de kans dat je wordt afgeleid? Tik alles aan wat klopt.', o:['Je navigatie instellen tijdens het rijden','Eten achter het stuur','Je route vooraf bekijken','Een gesprek met passagiers achterin','Je telefoon in je hand houden'], a:[0,1,3,4], u:'Je route vooraf bekijken vermindert afleiding juist.', art:'RVV 1990, art. 61a en WVW 1994, art. 5'},
    {t:'mc', k:'nul-emissiezone', b:'milieu-zone', v:'Je rijdt met een dieselbestelbus een nul-emissiezone binnen. Wat kan er gebeuren?', o:['Je krijgt een boete als je voertuig er niet is toegestaan','Niets; de zone geldt alleen voor vrachtwagens','Je moet er je motor uitzetten en stapvoets rijden'], a:0, u:'De nul-emissiezone geldt voor bedrijfs- en vrachtauto’s en wordt met camera’s op kenteken gecontroleerd. Voor dieselpersonenauto’s geldt de gewone milieuzone.', art:'RVV 1990, art. 86e'},
    {t:'jn', k:'start-stop', b:'milieu-stilstaan', v:'Je auto zet de motor vanzelf uit als je voor het stoplicht stilstaat. Is dat normaal?', a:0, u:'Ja. Dat is het start-stopsysteem. Het bespaart brandstof in de stad en bij files, en start de motor weer als je de rem of koppeling loslaat.', art:'Het Nieuwe Rijden'},
    {t:'mc', k:'uitrollen-stoplicht', b:'tekens-licht-geel', v:'Je nadert een stoplicht dat net op rood springt. Wat is het zuinigst wat je kunt doen?', o:['Gas loslaten en uitrollen tot je moet remmen','Doorrijden en vlak voor het licht stevig remmen','In een lage versnelling blijven gas geven'], a:0, u:'Uitrollen verbruikt nauwelijks brandstof en voorkomt onnodig remmen. Kijk ver vooruit.', art:'Het Nieuwe Rijden'},
    {t:'mc', k:'alcohol-ochtend', b:'wet-alcohol', v:'Je hebt gisteravond veel gedronken en wilt ’s ochtends rijden. Wat geldt?', o:['Je kunt nog steeds boven de grens zitten','Na een nacht slapen ben je altijd nuchter','Alleen sterke drank blijft zo lang hangen'], a:0, u:'Je lichaam breekt ongeveer een glas per uur af. Na een zware avond zit je ’s ochtends nog makkelijk boven de grens.', art:'WVW 1994, art. 8'},
    {t:'mc', k:'adas-cruise-wanneer', b:'milieu-cruise', v:'Je rijdt op een rustige, vlakke snelweg. Wat levert cruise control je hier op?', o:['Een constante snelheid, wat rustiger en zuiniger rijdt','Een kortere remweg bij een noodstop','Dat je even minder hoeft op te letten'], a:0, u:'Cruise control houdt je snelheid constant en dat scheelt brandstof. Hij neemt het kijken en anticiperen niet van je over: jij blijft de bestuurder.', art:'Rijprocedure B, hoofdstuk 1 en 2'},
    {t:'mc', k:'adas-cruise-uit', b:'veilig-gladheid', v:'Het wegdek is hier glad en je cruise control staat aan. Wat doe je?', o:['Je zet hem uit en regelt je snelheid zelf','Je laat hem aan maar stelt een lagere snelheid in','Je laat hem aan; het systeem merkt gladheid zelf'], a:0, u:'Op glad wegdek, in de stad en in druk verkeer zet je cruise control uit. Je wilt gas en snelheid dan zelf in de hand houden.', art:'Rijprocedure B, hoofdstuk 1 en 2'},
    {t:'jn', k:'adas-isa-snelheid', b:'tekens-matrix', v:'Je snelheidsassistent geeft 100 aan, maar op het bord boven de weg staat 90. Volg je het bord?', a:0, u:'Ja. De borden langs en boven de weg zijn leidend. Een snelheidsassistent leest borden en kaartgegevens en kan zich vergissen.', art:'Rijprocedure B, hoofdstuk 1 en 2'}
  ],
  puzzles:[]
},
{
  id:'wet', nr:7, titel:'Wetgeving', kleur:'--m-wet',
  samenvatting:'Rijbewijs, beginnend bestuurder, APK, verzekering, documenten, lading en aansprakelijkheid.',
  lessons:[
    {t:'Rijbewijs B', b:'Je mag vanaf je 18e zelfstandig rijden met een rijbewijs B. Met 2toDrive kun je vanaf 16,5 jaar theorie doen, vanaf 17 je examen halen en tot je 18e alleen rijden met een coach.', a:'Reglement rijbewijzen'},
    {t:'Geldigheid', b:'Het theoriecertificaat is anderhalf jaar geldig. Een rijbewijs is in principe tien jaar geldig; vanaf 70 jaar wordt die termijn korter en gelden extra keuringen.', a:'Reglement rijbewijzen en WVW 1994, art. 122'},
    {t:'Beginnend bestuurder', b:'Je bent beginnend bestuurder gedurende vijf jaar na het halen van je eerste rijbewijs, en zeven jaar als je via 2toDrive begonnen bent. Je alcohollimiet is dan 0,2 promille en bij herhaalde zware overtredingen volgt een onderzoek naar je rijvaardigheid.', a:'WVW 1994, art. 8 lid 3 en art. 130 t/m 134'},
    {t:'Wat moet je bij je hebben', b:'Op vordering van de politie moet je je rijbewijs én je kentekenbewijs kunnen overhandigen. Neem de kentekencard dus mee. In het buitenland komen daar vaak de groene kaart en soms een internationaal rijbewijs bij.', a:'WVW 1994, art. 160'},
    {t:'APK', b:'Een personenauto op benzine die jonger is dan vier jaar hoeft nog niet gekeurd. Daarna geldt kort gezegd: na vier jaar de eerste keuring, dan om de twee jaar en vanaf acht jaar oud jaarlijks. Diesel en LPG moeten eerder en vaker.', a:'Regeling voertuigen'},
    {t:'Verzekering', b:'Een WA-verzekering is verplicht voor elk motorvoertuig met kenteken, ook als het stilstaat. Zonder verzekering krijg je automatisch een boete via de RDW.', a:'Wet aansprakelijkheidsverzekering motorrijtuigen'},
    {t:'Massa’s en passagiers', b:'Met rijbewijs B rijd je een auto met een toegestane maximummassa tot 3.500 kg en maximaal acht passagiers naast de bestuurder. Voor een zwaardere combinatie heb je code 96 of rijbewijs BE nodig.', a:'Reglement rijbewijzen'},
    {t:'Lading', b:'Lading moet goed vastzitten en mag het zicht en de verlichting niet belemmeren. Achter de auto mag lading maximaal één meter uitsteken, met een markeringsbord. Aan de voorkant mag alleen ondeelbare lading uitsteken, ook hooguit één meter.', a:'Regeling voertuigen, art. 5.18.12 en 5.18.13'},
    {t:'Gevaarlijke overtredingen', b:'Artikel 5 WVW verbiedt gevaar of hinder veroorzaken. Artikel 6 gaat over een ongeval met letsel of de dood door schuld. Artikel 7 verbiedt doorrijden na een ongeval. Artikel 8 gaat over rijden onder invloed.', a:'WVW 1994, art. 5 t/m 8'},
    {t:'Ontzegging van de rijbevoegdheid', b:'Een rechter kan je rijbevoegdheid ontzeggen. Rijd je toch, dan is dat een misdrijf. Bij zware overtredingen kan je rijbewijs ook direct ingevorderd worden.', a:'WVW 1994, art. 9 en 164'},
    {t:'Aanhangwagen', b:'Met rijbewijs B mag je een aanhanger trekken als de combinatie niet zwaarder is dan 3.500 kg. Met code 96 mag dat tot 4.250 kg, met rijbewijs BE tot 7.000 kg.', a:'Reglement rijbewijzen', ill:'aanhanger'},
    {t:'Kenteken en RDW', b:'Elk motorvoertuig heeft een kenteken dat bij de RDW geregistreerd staat. Verkoop je je auto, dan zorg je voor overschrijving en een vrijwaringsbewijs; anders blijf je aansprakelijk voor boetes en belasting.', a:'WVW 1994, art. 36, 50 en 51a'}
  ],
  questions:[
    {t:'mc', k:'theoriecertificaat-geldig', b:'wet-rijbewijs', v:'Je haalt je theorie-examen. Hoelang kun je daarna praktijkexamen doen met dat certificaat?', o:['Anderhalf jaar','Zes maanden','Vijf jaar'], a:0, u:'Het theoriecertificaat is anderhalf jaar geldig. Daarna moet je opnieuw theorie-examen doen.', art:'Reglement rijbewijzen'},
    {t:'mc', k:'beginnend-bestuurder-duur', b:'wet-rijbewijs', v:'Je haalt op je 18e je rijbewijs. Hoelang ben je dan beginnend bestuurder?', o:['Vijf jaar','Drie jaar','Tot je 25e'], a:0, u:'Vijf jaar. Ben je via 2toDrive begonnen, dan is het zeven jaar.', art:'WVW 1994, art. 8 lid 3 en Reglement rijbewijzen'},
    {t:'jn', k:'wa-verzekering-stilstaand', v:'Je auto staat maanden stil op je eigen oprit. Moet hij dan toch WA-verzekerd zijn?', a:0, u:'Ja. Zolang het voertuig een kenteken op jouw naam heeft en niet geschorst is, is een WA-verzekering verplicht.', art:'Wet aansprakelijkheidsverzekering motorrijtuigen'},
    {t:'mc', k:'maximummassa-rijbewijs-b', b:'wet-kenteken', v:'Je wilt een busje huren. Tot welke toegestane maximummassa mag je dat met rijbewijs B besturen?', o:['3.500 kg','2.500 kg','5.000 kg'], a:0, u:'Met rijbewijs B mag je een voertuig tot 3.500 kg toegestane maximummassa besturen, met maximaal acht passagiers naast jezelf.', art:'Reglement rijbewijzen'},
    {t:'mc', k:'lading-achter-uitsteken', b:'voert-lading', v:'Je vervoert een plank die achter uit je auto steekt. Hoeveel mag die maximaal uitsteken?', o:['Een meter, met een markeringsbord erop','Een halve meter, zonder markeringsbord','Zoveel je wilt, als het maar goed vastzit'], a:0, u:'Achter mag lading maximaal een meter uitsteken en dan moet er een rood-wit markeringsbord aan.', art:'Regeling voertuigen, art. 5.18.12'},
    {t:'jn', k:'kentekenbewijs-tonen', b:'wet-kenteken', v:'De politie houdt je staande en vraagt om je kentekenbewijs. Moet je dat kunnen laten zien?', a:0, u:'Ja. Op vordering van de politie moet je zowel je rijbewijs als je kentekenbewijs overhandigen. De kentekencard hoort dus bij je te zijn.', art:'WVW 1994, art. 160'},
    {t:'mc', k:'alcoholgrens-beginner', b:'wet-alcohol', v:'Je bent beginnend bestuurder en gaat uit eten. Welke alcoholgrens geldt voor jou?', o:['0,2 promille','0,5 promille','0,8 promille'], a:0, u:'0,2 promille, oftewel 88 microgram per liter uitgeademde lucht.', art:'WVW 1994, art. 8'},
    {t:'mc', k:'doorrijden-na-ongeval', b:'veilig-ongeval', v:'Je rijdt weg na een aanrijding zonder je gegevens achter te laten. Wat is dat?', o:['Een misdrijf, ook als er alleen schade is','Een gewone overtreding met een boete','Niet strafbaar, zolang je het later meldt'], a:0, u:'Het verlaten van de plaats van een ongeval zonder je gegevens achter te laten is een misdrijf.', art:'WVW 1994, art. 7'},
    {t:'multi', k:'verplicht-op-de-weg', v:'Wat moet in orde zijn voordat je de weg op gaat? Tik alles aan wat klopt.', o:['Een geldige APK','Een WA-verzekering','Een geldig kenteken','Een veiligheidshesje','Een brandblusser'], a:[0,1,2], u:'Een hesje en een brandblusser zijn aan te raden, maar in Nederland niet verplicht.', art:'WVW 1994 en Regeling voertuigen'},
    {t:'mc', k:'leeftijd-zelfstandig-rijden', b:'wet-rijbewijs', v:'Vanaf welke leeftijd mag je zonder begeleider rijden met rijbewijs B?', o:['18 jaar','17 jaar','21 jaar'], a:0, u:'Vanaf 18 jaar. Met 2toDrive mag je vanaf 17 rijden, maar alleen met een coach naast je.', art:'Reglement rijbewijzen'},
    {t:'jn', k:'combinatie-5000', b:'voert-aanhanger', v:'Je auto met aanhanger weegt samen 5.000 kg. Mag je daarmee rijden met alleen rijbewijs B?', a:1, u:'Nee. Met B is de combinatie maximaal 3.500 kg. Met code 96 mag het tot 4.250 kg en met rijbewijs BE tot 7.000 kg.', art:'Reglement rijbewijzen'},
    {t:'mc', k:'auto-verkopen', b:'wet-kenteken', v:'Je verkoopt je auto aan een particulier. Wat regel je?', o:['Je laat het kenteken overschrijven en bewaart je vrijwaringsbewijs','Je geeft je verzekering door aan de koper','Je stuurt het kentekenbewijs naar de gemeente'], a:0, u:'Zonder vrijwaringsbewijs blijf je aansprakelijk voor boetes, wegenbelasting en verzekering.', art:'WVW 1994, art. 50 en 51a'},
    {t:'mc', k:'apk-eerste-keuring', b:'voert-apk', v:'Je koopt een nieuwe benzineauto. Wanneer moet hij voor het eerst op APK?', o:['Na vier jaar','Na een jaar','Na acht jaar'], a:0, u:'Een nieuwe benzinepersonenauto moet na vier jaar voor het eerst gekeurd. Diesel en LPG moeten eerder en vaker.', art:'Regeling voertuigen'},
    {t:'jn', k:'rijden-tijdens-ontzegging', v:'De rechter heeft je rijbevoegdheid ontzegd en je rijdt toch. Is dat een misdrijf?', a:0, u:'Ja. Rijden tijdens een ontzegging is strafbaar als misdrijf en kan leiden tot een celstraf.', art:'WVW 1994, art. 9'},
    {t:'fill', k:'rijbewijs-geldigheid', b:'wet-rijbewijs', v:'Je haalt je rijbewijs op je 20e. Hoeveel jaar is het in principe geldig? (alleen het getal)', a:'10', u:'Tien jaar. Vanaf 70 jaar geldt een kortere termijn en zijn er extra keuringen.', art:'WVW 1994, art. 122'},
    {t:'mc', k:'invordering-rijbewijs', b:'wet-rijbewijs', v:'Een agent vordert je rijbewijs in na een ernstige snelheidsovertreding. Wat betekent dat voor jou?', o:['Je mag voorlopig niet rijden; het OM beslist wat er verder gebeurt','Je krijgt alleen een hogere boete','Je rijbewijs is definitief ongeldig'], a:0, u:'Bij invordering raak je het rijbewijs tijdelijk kwijt. Het Openbaar Ministerie beslist daarna wat er verder gebeurt.', art:'WVW 1994, art. 164'},
    {t:'multi', k:'gevaar-en-hinder', b:'veilig-volgafstand', v:'Je rijdt op de weg. Welke van deze dingen vallen onder gevaar of hinder veroorzaken? Tik alles aan wat klopt.', o:['Gevaar veroorzaken op de weg','Het verkeer hinderen','3 km per uur te hard rijden','Bumperkleven','Doorrijden na een ongeval'], a:[0,1,3], u:'Artikel 5 van de Wegenverkeerswet gaat over gevaar en hinder. Doorrijden na een ongeval valt onder artikel 7, en een kleine snelheidsovertreding is een gewone overtreding.', art:'WVW 1994, art. 5 en 7'},
    {t:'mc', k:'aantal-passagiers', v:'Hoeveel passagiers mag je naast jezelf vervoeren met rijbewijs B?', o:['Acht','Vier','Twaalf'], a:0, u:'Maximaal acht passagiers naast de bestuurder, en alleen als er voor iedereen een zitplaats met gordel is.', art:'Reglement rijbewijzen'},
    {t:'jn', k:'lading-voor-uitsteken', b:'voert-lading', v:'Je bindt een vlag aan een ladder die vooraan uitsteekt. Mag je zo rijden?', a:1, u:'Nee, niet zomaar. Aan de voorkant mag alleen ondeelbare lading uitsteken, en ook dan hooguit een meter. Achter mag het wel, maximaal een meter met markeringsbord.', art:'Regeling voertuigen, art. 5.18.12 en 5.18.13'},
    {t:'mc', k:'puntenstelsel-beginner', b:'wet-rijbewijs', v:'Je bent beginnend bestuurder en hebt meerdere zware overtredingen begaan. Wat kan er gebeuren?', o:['Je moet een onderzoek naar je rijvaardigheid doen en kunt je rijbewijs kwijtraken','Je krijgt alleen hogere boetes','Je krijgt een waarschuwingsbrief en verder niets'], a:0, u:'Beginnende bestuurders met meerdere zware overtredingen moeten een onderzoek ondergaan; het rijbewijs kan ongeldig worden verklaard.', art:'WVW 1994, art. 130 t/m 134'},
    {t:'mc', k:'caravan-rijbewijs', b:'voert-aanhanger', v:'Je auto weegt 1.600 kg en je caravan 1.200 kg. Wat heb je nodig om hiermee te rijden?', o:['Rijbewijs B is genoeg','Rijbewijs BE','Code 96 op je rijbewijs'], a:0, u:'De combinatie weegt 2.800 kg en blijft onder 3.500 kg, dus rijbewijs B volstaat. Let ook op het maximum trekgewicht van je auto.', art:'Reglement rijbewijzen'},
    {t:'hotspot', k:'kenteken-massa-aanwijzen', b:'wet-kenteken', v:'Tik het veld aan waarop de toegestane maximummassa van je auto staat.', a:{x:10,y:59,w:79,h:16}, u:'De toegestane maximummassa is wat de auto met lading en inzittenden maximaal mag wegen. Trek er de massa ledig voertuig vanaf en je weet je laadvermogen.', art:'Regeling voertuigen'}
  ],
  puzzles:[]
},
{
  id:'voertuig', nr:8, titel:'Voertuigkennis', kleur:'--m-voertuig',
  samenvatting:'Dashboardlampjes, banden, remmen, verlichting, vloeistoffen en rijhulpsystemen (ADAS).',
  lessons:[
    {t:'Kleuren op je dashboard', b:'Rood betekent: stop zo snel mogelijk veilig en zet de motor uit. Oranje of geel betekent: er is iets mis, laat het nakijken. Groen en blauw zijn alleen informatie, zoals groot licht of richtingaanwijzer.', a:'Regeling voertuigen', ill:'dashboard'},
    {t:'Rode lampjes die je niet mag negeren', b:'Oliedruk (oliekannetje), laadstroom (accu), koelvloeistoftemperatuur en het remsysteem. Doorrijden met een brandend oliedruklampje kan je motor binnen enkele kilometers vernielen.', a:'Regeling voertuigen', ill:'dashboard'},
    {t:'Oranje lampjes', b:'Motorstoring (motorsymbool), ABS, ESP, bandenspanning en roetfilter. Je kunt meestal nog rijden, maar een systeem werkt niet of minder goed. Laat het snel nakijken.', a:'Regeling voertuigen'},
    {t:'Banden', b:'De wettelijke minimale profieldiepte is 1,6 millimeter. Voor winterbanden wordt vier millimeter aangeraden, maar dat is een advies. Controleer ook op scheuren en bobbels en op gelijkmatige slijtage.', a:'Regeling voertuigen, art. 5.2.27', ill:'bandprofiel'},
    {t:'Remmen', b:'ABS voorkomt blokkeren zodat je kunt blijven sturen. De remassistent (BAS) versterkt je remkracht bij een noodstop. ESP of ESC remt individuele wielen af om slippen te voorkomen.', a:'Regeling voertuigen'},
    {t:'Verlichting controleren', b:'Dimlicht, groot licht, achterlicht, remlicht, richtingaanwijzers, kentekenverlichting en mistlicht moeten werken. Een kapot remlicht zie je zelf niet; laat iemand meekijken.', a:'RVV 1990, art. 32 t/m 41', ill:'dimlicht'},
    {t:'Vloeistoffen', b:'Motorolie, koelvloeistof, remvloeistof en ruitensproeiervloeistof controleer je regelmatig. Olie peil je op een vlakke ondergrond met koude motor.', a:'Regeling voertuigen'},
    {t:'Massa’s', b:'De massa ledig voertuig is het gewicht van de lege auto. De toegestane maximummassa is wat de auto maximaal mag wegen inclusief lading en inzittenden. Het verschil is je laadvermogen.', a:'Regeling voertuigen'},
    {t:'ADAS: rijhulpsystemen', b:'Adaptieve cruisecontrol houdt afstand, de rijstrookassistent stuurt je terug, dodehoekdetectie waarschuwt bij voertuigen naast je en de noodremassistent remt zelf. Ze ondersteunen, ze nemen het niet over.', a:'Regeling voertuigen en EU-verordening 2019/2144'},
    {t:'Wanneer een rijhulpsysteem je niet helpt', b:'Camera’s en radar werken minder goed bij mist, sneeuw, fel tegenlicht, een vieze sensor of vervaagde strepen. Ook bij wegwerkzaamheden met tijdelijke strepen kan een rijstrookassistent de verkeerde lijn volgen. Weet dus wat je systeem wel en niet kan, en zet het uit als het je in de weg zit.', a:'Rijprocedure B, hoofdstuk 1 en 2'},
    {t:'Je blijft verantwoordelijk', b:'Ook met ADAS aan ben jij de bestuurder. Een systeem kan uitvallen, een fietser missen of in slecht weer niet werken. Blijf kijken en hou je handen aan het stuur.', a:'WVW 1994, art. 5'},
    {t:'ISA: snelheidsassistent', b:'Nieuwe auto’s hebben een intelligente snelheidsassistent die waarschuwt als je te hard rijdt. Hij leest borden en kaartgegevens, en kan zich vergissen. De borden langs de weg zijn leidend.', a:'EU-verordening 2019/2144'},
    {t:'Elektrisch en hybride', b:'Een elektrische auto is stil, dus voetgangers horen je minder goed. Regeneratief remmen laadt de accu op als je gas loslaat; het remlicht gaat daarbij niet altijd aan.', a:'Regeling voertuigen'}
  ],
  questions:[
    {t:'mc', k:'oliedruklampje', b:'voert-dashboard', v:'Tijdens het rijden gaat het rode oliedruklampje branden. Wat doe je?', o:['Zo snel mogelijk veilig stoppen en de motor uitzetten','Doorrijden tot de garage en onderweg olie bijvullen','De komende week een afspraak maken bij de garage'], a:0, u:'Een rood oliedruklampje betekent direct gevaar voor de motor. Stop veilig en zet de motor uit.', art:'Regeling voertuigen'},
    {t:'mc', k:'motorstoringslampje', b:'voert-dashboard', v:'Er gaat een oranje motorstoringslampje branden. Wat betekent dat voor jou?', o:['Er is een storing; je kunt meestal nog rijden maar laat het snel nakijken','Je moet onmiddellijk stoppen en de motor uitzetten','Je motor is nog koud en moet eerst op temperatuur komen'], a:0, u:'Oranje betekent: er is iets mis en een systeem werkt niet goed. Rijd rustig door en laat het snel controleren.', art:'Regeling voertuigen'},
    {t:'fill', k:'profieldiepte-minimaal', b:'voert-bandprofiel', v:'Je controleert je banden. Hoeveel millimeter profiel moet een band wettelijk minimaal hebben? (schrijf het met een komma, bijvoorbeeld 2,5)', a:'1,6', u:'1,6 millimeter. Daaronder is de band afgekeurd en neemt de grip op nat wegdek sterk af.', art:'Regeling voertuigen, art. 5.2.27'},
    {t:'mc', k:'kleur-direct-stoppen', b:'voert-dashboard', v:'Welke kleur dashboardlampje betekent dat je zo snel mogelijk moet stoppen?', o:['Rood','Oranje','Groen'], a:0, u:'Rood betekent een ernstig probleem: zoek een veilige plek, stop en zet de motor uit.', art:'Regeling voertuigen'},
    {t:'multi', k:'rode-lampjes', b:'voert-dashboard', v:'Je kijkt naar je dashboard. Welke van deze lampjes zijn rood en wijzen op een ernstig probleem? Tik alles aan wat klopt.', o:['Oliedruk','Laadstroom (accu)','Richtingaanwijzer','Koelvloeistoftemperatuur','Remsysteem'], a:[0,1,3,4], u:'De richtingaanwijzer is een groen informatielampje. Bij oliedruk, koelvloeistof en remsysteem stop je direct; bij het accu-lampje rijd je op de accu verder en zoek je snel een garage.', art:'Regeling voertuigen'},
    {t:'mc', k:'esp', v:'Je auto dreigt in een natte bocht weg te glijden en het ESP grijpt in. Wat doet dat systeem?', o:['Het remt losse wielen af en neemt gas terug om slippen te voorkomen','Het houdt automatisch afstand tot je voorligger','Het stuurt je terug tussen de strepen'], a:0, u:'ESP of ESC merkt dat de auto een andere kant op gaat dan je stuurt en remt gericht af. Het haalt geen grip terug die er niet is: rijd op gladde wegen langzamer.', art:'Regeling voertuigen'},
    {t:'jn', k:'adas-acc-opletten', b:'milieu-cruise', v:'Je adaptieve cruisecontrol houdt zelf afstand. Mag je dan minder op het verkeer letten?', a:1, u:'Nee. Het systeem ondersteunt je, maar jij blijft als bestuurder verantwoordelijk en moet blijven kijken.', art:'Rijprocedure B, hoofdstuk 1 en 2'},
    {t:'mc', k:'dodehoekwaarschuwing', b:'veilig-dodehoek', v:'Er gaat een lampje branden in je buitenspiegel terwijl je van rijstrook wilt wisselen. Wat doe je?', o:['Je blijft op je strook en kijkt zelf over je schouder','Je wisselt toch; het systeem waarschuwt alleen bij groot gevaar','Je zet je alarmlichten aan en wisselt langzaam'], a:0, u:'Dat is de dodehoekwaarschuwing: er rijdt iets naast of schuin achter je. Het systeem ziet niet alles, dus kijk ook zelf over je schouder.', art:'Rijprocedure B, hoofdstuk 1 en 2'},
    {t:'mc', k:'olie-peilen', v:'Je wilt je motorolie peilen. Hoe doe je dat goed?', o:['Op een vlakke ondergrond met een afgekoelde motor','Direct na het uitzetten van een hete motor','Terwijl de motor stationair draait'], a:0, u:'Op een vlakke ondergrond met afgekoelde motor, zodat alle olie in het carter staat.', art:'Regeling voertuigen'},
    {t:'jn', k:'remlicht-kapot', b:'voert-verlichting', v:'Je remlicht is kapot. Merk je dat vanzelf tijdens het rijden?', a:1, u:'Nee. Je ziet je eigen remlichten niet. Laat iemand meekijken of gebruik de weerspiegeling in een etalageruit.', art:'Regeling voertuigen, afdeling 5.2'},
    {t:'mc', k:'laadvermogen', b:'wet-kenteken', v:'Je wilt weten hoeveel je nog mag meenemen aan lading en inzittenden. Hoe reken je dat uit?', o:['Toegestane maximummassa min de massa ledig voertuig','Toegestane maximummassa plus het gewicht van de aanhanger','De massa ledig voertuig gedeeld door twee'], a:0, u:'Het verschil tussen de toegestane maximummassa en de massa ledig voertuig is je laadvermogen. Beide staan op je kentekenbewijs.', art:'Regeling voertuigen'},
    {t:'mc', k:'adas-rijstrookassistent-overrulen', v:'Je wijkt bewust uit voor een kuil en je rijstrookassistent stuurt tegen. Wat doe je?', o:['Je stuurt zelf door; jij hebt de leiding over de auto','Je laat het stuur even los zodat het systeem het doet','Je zet je alarmlichten aan en rijdt rechtdoor'], a:0, u:'Een rijstrookassistent kan je corrigeren, maar jij stuurt. Je kunt het systeem overrulen en zo nodig uitzetten.', art:'Rijprocedure B, hoofdstuk 1 en 2'},
    {t:'jn', k:'winterbanden-vier-mm', b:'voert-bandprofiel', v:'Je winterbanden hebben nog 3 millimeter profiel. Zijn ze dan nog goed voor de sneeuw?', a:1, u:'Nee, niet echt. Wettelijk geldt 1,6 millimeter, maar bij winterbanden wordt vier millimeter aangehouden: daaronder neemt de grip op sneeuw sterk af.', art:'Advies van de bandenbranche; wettelijk geldt 1,6 mm'},
    {t:'mc', k:'elektrisch-remmen', v:'Je rijdt elektrisch en laat het gaspedaal los. Wat gebeurt er?', o:['De auto vertraagt al en laadt de accu op','De auto rolt verder uit dan een benzineauto','Er gebeurt niets tot je remt'], a:0, u:'Regeneratief remmen vertraagt je al bij het loslaten van het gaspedaal. Bij lichte vertraging gaan de remlichten niet aan, dus kijk in je spiegel voordat je sterk laat vertragen.', art:'Regeling voertuigen'},
    {t:'mc', k:'bandenspanningslampje', b:'voert-dashboard', v:'Op je dashboard brandt een oranje lampje met een uitroepteken in een hoefijzervorm. Wat is er aan de hand?', o:['Je bandenspanning is te laag','Je groot licht staat aan','Je mistlicht achter staat aan'], a:0, u:'Dat symbool staat voor het bandenspanningscontrolesysteem. Controleer je spanning bij koude banden.', art:'Regeling voertuigen'},
    {t:'multi', k:'verlichting-apk', b:'voert-verlichting', v:'Welke verlichting moet werken als je auto gekeurd wordt? Tik alles aan wat klopt.', o:['Dimlicht','Remlicht','Kentekenverlichting','Interieurverlichting','Richtingaanwijzers'], a:[0,1,2,4], u:'Interieurverlichting hoort niet bij de verplichte voertuigverlichting.', art:'Regeling voertuigen'},
    {t:'mc', k:'adas-noodrem', v:'Je auto heeft een noodremassistent. Waar moet je rekening mee houden?', o:['Hij remt alleen als een botsing dreigt en werkt niet in elke situatie','Hij vervangt je eigen rem, dus je hoeft zelf niet meer te remmen','Hij houdt automatisch afstand tot je voorligger'], a:0, u:'De noodremassistent remt als het systeem een dreigende aanrijding ziet. Hij mist soms een fietser, een kruisend voertuig of iets in slecht zicht. Jij remt zelf.', art:'Rijprocedure B, hoofdstuk 1 en 2'},
    {t:'jn', k:'adas-isa-vergissing', b:'tekens-bord-onderbord', v:'Je snelheidsassistent geeft een andere snelheid aan dan het bord langs de weg. Kan het systeem zich vergissen?', a:0, u:'Ja. De assistent leest borden en kaartgegevens en kan fout zitten, bijvoorbeeld bij een onderbord of tijdelijke borden. Het bord langs de weg is leidend.', art:'Rijprocedure B, hoofdstuk 1 en 2'},
    {t:'mc', k:'koelvloeistof-rood', b:'voert-dashboard', v:'Het rode lampje voor de koelvloeistoftemperatuur gaat branden. Wat doe je?', o:['Stoppen, de motor uitzetten en hem laten afkoelen','Doorrijden met de kachel vol open','De dop eraf halen en koud water bijvullen'], a:0, u:'Stop en laat de motor afkoelen. Koud water op een hete motor kan de koppakking vernielen.', art:'Regeling voertuigen'},
    {t:'mc', k:'elektrisch-stil', v:'Je rijdt stapvoets elektrisch door een winkelstraat. Waarom is dat extra oppassen?', o:['Voetgangers horen je nauwelijks aankomen','Je remweg is veel langer dan met benzine','Je verlichting werkt bij lage snelheid niet'], a:0, u:'Een elektrische auto is bij lage snelheid bijna onhoorbaar. Nieuwe auto’s hebben daarom een kunstmatig geluid, maar reken er niet op dat men je hoort.', art:'EU-verordening 540/2014'},
    {t:'mc', k:'kleur-informatielampje', b:'voert-dashboard', v:'Welke kleur dashboardlampje is alleen informatie, zoals bij je richtingaanwijzer?', o:['Groen','Oranje','Rood'], a:0, u:'Groen en blauw zijn informatielampjes. Blauw is standaard voor groot licht.', art:'Regeling voertuigen'},
    {t:'mc', k:'adas-sensor-vuil', b:'veilig-mist', v:'Je rijdt in mist en je auto meldt dat de rijhulpsystemen niet beschikbaar zijn. Wat doe je?', o:['Je rijdt verder zonder die hulp en past je snelheid aan het zicht aan','Je rijdt door op dezelfde snelheid; de systemen komen vanzelf terug','Je zet je alarmlichten aan zodat anderen je zien'], a:0, u:'Camera en radar werken slecht bij mist, sneeuw of een vieze sensor. Reken er dan niet op en rijd zo dat je binnen je zichtafstand kunt stoppen.', art:'Rijprocedure B, hoofdstuk 1 en 2'},
    {t:'hotspot', k:'dashboard-rood-aantikken', b:'voert-dashboard', v:'Tik het lampje aan dat betekent dat je zo snel mogelijk moet stoppen.', a:{x:9,y:24,w:17,h:23}, u:'Een rood lampje betekent direct gevaar voor je auto of je veiligheid. Zoek een veilige plek, stop en zet de motor uit.', art:'Regeling voertuigen'}
  ],
  puzzles:[]
}
];
